/// <summary>
/// Builds the map of fields to copy between the source tmp table intance to the destination tmp table instance.
/// </summary>
/// <param name = "_copyMapBuilder">The instance of <c>CustAccountStatementExtDPTmpTableCopyMapBuilder</c> used to build the field map.</param>
protected void mapCustAccountStatementExtTmpToNewTempTableInstance(CustAccountStatementExtDPTmpTableCopyMapBuilder _copyMapBuilder)
{
    next mapCustAccountStatementExtTmpToNewTempTableInstance (_copyMapBuilder);
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGCompanyEmail));
    // MPJ_4044_CustomerAccountStatement - kscerri - 21/07/2021 - Start
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGBPayBillerCode));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGBPayReference));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGRegNum));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGBankAccountNum));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGRemittanceEmail));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGCustServiceNum));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGFooterNote));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGKnownAs));
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGBsbReference)); 
    _copyMapBuilder.addFieldToMap(fieldNum(CustAccountStatementExtTmp, KPMGCurrency));        
    // MPJ_4044_CustomerAccountStatement - kscerri - 21/07/2021 - End
}

    public void processReport()
    {
        next processReport();

        Date                            duedate1, duedate2, duedate3, duedate4, dateNull, toDate;
        AmountCur                       balanceDue1, balanceDue2, balanceDue3, balanceDue4,test;
        int                             flagValue = 0;
        CustAccountStatementExtTmp      metCustAccountStatementExtTmp = this.getCustAccountStatementExtTmp();
        CustAccountStatementExtContract metInternalContract = this.parmDataContract() as CustAccountStatementExtContract;
        
        dateNull = Global::DateNull();

        toDate = metInternalContract.parmToDate();

        while select
            sum(CustTrans_Credit),
            sum(CustTrans_Debit),
            CustTrans_DueDate
        from
            metCustAccountStatementExtTmp
        group by
            CustTrans_DueDate
        where
            metCustAccountStatementExtTmp.CustTrans_DueDate != Global::DateNull() &&
            metCustAccountStatementExtTmp.CustTrans_DueDate > toDate &&
            metCustAccountStatementExtTmp.FlagMainData == 19
        {
            flagValue++;

            if (flagValue == 1)
            {
                duedate1        = metCustAccountStatementExtTmp.CustTrans_DueDate;
                balanceDue1     = metCustAccountStatementExtTmp.CustTrans_Debit
                                    + metCustAccountStatementExtTmp.CustTrans_Credit;
            }

            if (flagValue == 2)
            {
                duedate2        = metCustAccountStatementExtTmp.CustTrans_DueDate;
                balanceDue2     = metCustAccountStatementExtTmp.CustTrans_Debit
                                    + metCustAccountStatementExtTmp.CustTrans_Credit;
            }

            if (flagValue == 3)
            {
                duedate3        = metCustAccountStatementExtTmp.CustTrans_DueDate;
                balanceDue3     = metCustAccountStatementExtTmp.CustTrans_Debit
                                    + metCustAccountStatementExtTmp.CustTrans_Credit;
            }

            if (flagValue >= 4)
            {
                if (flagValue == 4)
                {
                    duedate4     = metCustAccountStatementExtTmp.CustTrans_DueDate;
                }
                balanceDue4     = metCustAccountStatementExtTmp.CustTrans_Debit
                                    + metCustAccountStatementExtTmp.CustTrans_Credit
                                    + balanceDue4;                   
            }
        }

        update_recordset metCustAccountStatementExtTmp
            setting 
                KPMGDueDate1     = duedate1,
                KPMGBalanceDue1  = balanceDue1,
                KPMGDueDate2     = duedate2,
                KPMGBalanceDue2  = balanceDue2,
                KPMGDueDate3     = duedate3,
                KPMGBalanceDue3  = balanceDue3,
                KPMGDueDate4     = duedate4,
                KPMGBalanceDue4  = balanceDue4
            where metCustAccountStatementExtTmp.Balance01 != 0;

    }
